const pages={playlists:['재생목록','layers','PLAYLISTS'],groups:['장치 그룹','server','GROUPS'],schedules:['시간표','clock','SCHEDULE'],reports:['운영 기록','grid','ACTIVITY'],devices:['장치 관리','server','PLAYER DEVICES'],registration:['장치 연결 설정','settings','REGISTRATION'],dashboard:['대시보드','grid','OVERVIEW'],screens:['출력 화면 관리','screen','DISPLAYS'],ads:['광고판 관리','ads','ADVERTISING'],menus:['메뉴판 관리','menu','MENU BOARDS'],system:['시스템 정보','settings','SYSTEM'],support:['문의','help','SUPPORT'],editor:['콘텐츠 편집기','edit','CONTENT STUDIO'],media:['미디어','layers','MEDIA LIBRARY'],templates:['템플릿','layers','TEMPLATE COLLECTION']};
function readRoute(value=location.href){const url=new URL(value,location.origin);const view=url.hash.startsWith('#/')?new URL(url.hash.slice(1),location.origin):url;const name=view.pathname.split('/')[1];return {page:pages[name]?name:'dashboard',params:new URLSearchParams(view.search)}}
let {page,params}=readRoute();let navEpoch=0;const workspaces=new Map(),formWorkspaces=new Map(),scrollPositions=new Map();let editorKind='screen',activeTemplateId=null,selectionIds=new Set(),editorZoom=1,editorSnap=true,editorGrid=false,customFonts=[];
let csrfToken='',account={},savedTemplates=[],connections=[];
let screens=[],media=[],settings={},system={},players=[],dirty=false,draft=null,slideIndex=0,selectedElement=null,undoStack=[],redoStack=[],previewPlayer=null,toastTimer,mediaCallback=null,mediaKind=null,mediaSelection=new Set(),uploading=false;
