function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6000)}
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrfToken}:{})},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&!dirty)location.href='/login?next='+encodeURIComponent('/#/'+page+(params.size?'?'+params.toString():''));throw Error(data.error||'요청에 실패했습니다.')}return data}

function handle(fn){return async event=>{const target=event?.currentTarget;if(target?.tagName==='BUTTON')target.disabled=true;try{await fn(event)}catch(error){toast(error.message)}finally{if(target?.isConnected)target.disabled=false}}}
function markDirty(){dirty=true;const n=$('saveState');if(n){n.classList.add('dirty');n.textContent='● 저장하지 않은 변경사항'}}
window.addEventListener('beforeunload',event=>{if(dirty||[...workspaces.values()].some(w=>w.dirty)||[...formWorkspaces.values()].some(w=>w.dirty)){event.preventDefault();event.returnValue=''}});
