function empty(message='아직 등록된 디스플레이가 없습니다.',type='screen'){return `<div class="empty">${icon(type)}<h3>${message}</h3><p>새 디스플레이를 만들고 매장에 맞는 콘텐츠를 설정하세요.</p>${button('새 디스플레이','emptyAdd','plus','primary')}</div>`}
