function card(s){const content=s.content,mode=({slides:'자유 편집',images:'이미지 재생',videos:'영상 재생',menu:'메뉴 템플릿',basic:'기본 화면'})[content?.mode]||'기본 화면';return `<article class="screen-card"><div class="card-preview"><div class="card-topline"><span class="type-chip">${icon(({ads:'ads',menu:'menu',notice:'screen'})[s.type])}${types[s.type]}</span><span>${content?.aspect==='portrait'?'9:16 PORTRAIT':'16:9 LANDSCAPE'}</span></div><div class="stage" data-preview="${s.id}" aria-label="${esc(s.name)} 미리보기"></div></div><div class="card-body"><div style="display:flex;justify-content:space-between;align-items:start;gap:8px"><div class="screen-title-line"><h3>${esc(s.name)}</h3>${settings.mainScreenId===s.id?'<span class="main-screen-badge" title="메인 서버의 주 화면">주 화면</span>':''}</div><button class="card-rename" data-rename="${s.id}" aria-label="${esc(s.name)} 이름 변경" title="이름과 설치 위치 변경">${icon('edit')}</button><span class="badge ${s.status==='paused'?'paused':''}">${s.status==='active'?'● 활성':'Ⅱ 정지'}</span></div><div class="screen-location">${esc(s.location||'설치 위치 미지정')}</div><div class="screen-meta"><span>${mode}${content?.slides?.length?' · '+content.slides.length+'개 슬라이드':''}</span><span>v${s.revision}</span></div><div class="connection-line" data-connection="${s.id}"></div><div class="card-actions"><a class="btn" href="/editor?id=${s.id}">${icon('edit')}콘텐츠 편집</a><a class="btn" href="/display.html?id=${s.id}" target="_blank" rel="noopener">${icon('external')}미리보기</a><button class="icon-btn" title="${s.status==='active'?'일시 정지':'운영 재개'}" aria-label="${esc(s.name)} ${s.status==='active'?'일시 정지':'운영 재개'}" data-toggle="${s.id}">${icon(s.status==='active'?'pause':'play')}</button><a class="btn pair-btn" href="/devices">${icon('server')}장치에 화면 배정</a></div></div></article>`}

function bindCards(){bindConnections();document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>openScreenDialog(screens.find(s=>s.id===b.dataset.rename)));document.querySelectorAll('[data-pair]').forEach(b=>b.onclick=handle(()=>pairScreen(screens.find(s=>s.id===b.dataset.pair))));document.querySelectorAll('[data-preview]').forEach(host=>{const s=screens.find(x=>x.id===host.dataset.preview);players.push(new Playback(host,s,media))});document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=handle(async()=>{const s=screens.find(x=>x.id===b.dataset.toggle);await api('/api/screens/'+s.id,'PATCH',{status:s.status==='active'?'paused':'active',revision:s.revision});await refresh();toast('출력 상태가 변경되었습니다.')}))}
function dashboard(){destroyPlayers();releaseStages($('main'));$('main').innerHTML=head('콘텐츠와 출력 상태를 한눈에 확인하세요.',button('새 디스플레이','add','plus','primary'))+`<section class="hero"><div><div class="kicker">YOUR SPACE, YOUR SCREEN</div><h2>모든 화면에, 매장만의 이야기를.</h2><p>광고판과 메뉴판을 만들고, 연결된 화면에서 재생하세요.</p></div><a class="btn" href="/ads">광고판 만들기 ${icon('arrow')}</a></section><section class="stats">${[[screens.length,'전체 디스플레이','논리 화면 수','screen',''],[screens.filter(s=>s.status==='active').length,'출력 활성','출력이 활성화된 화면','play','green'],[screens.filter(s=>s.status==='paused').length,'일시 정지','설정된 출력 상태','pause','orange'],[media.length,'미디어 라이브러리','업로드한 이미지와 영상','layers','']].map(([n,label,sub,ico,cls])=>`<div class="stat"><div><div class="stat-label">${label}</div><div class="stat-value">${n}<small> 개</small></div><small>${sub}</small></div><div class="stat-icon ${cls}">${icon(ico)}</div></div>`).join('')}</section><div class="section-heading"><div><h2>디스플레이 미리보기 <span class="count">${screens.length}</span></h2><p>저장된 설정이 자동으로 반영됩니다. 이미지와 영상도 이곳에서 재생됩니다.</p></div><a class="btn" href="/screens">전체 관리 ${icon('arrow')}</a></div><section class="screen-grid">${screens.map(card).join('')||empty()}</section>`;bindAdd();bindCards()}
let listFilter='all',search='';
function listing(){destroyPlayers();releaseStages($('main'));const category=({ads:'ads',menus:'menu'})[page];$('main').innerHTML=head(({ads:'캔버스로 직접 만들거나, 이미지와 영상을 간단하게 반복 재생하세요.',menus:'메뉴 템플릿과 자유 편집으로 매장의 메뉴판을 만드세요.'})[page]||'화면별 콘텐츠, 설정, 독립 출력 URL을 관리하세요.',button('미디어 라이브러리','library','layers')+button('새 디스플레이','add','plus','primary'))+`<div class="toolbar"><div class="tabs">${(category?[[category,types[category]]]:[['all','전체'],['ads','광고판'],['menu','메뉴판'],['notice','안내판']]).map(([v,t])=>`<button class="tab ${listFilter===v||category?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" placeholder="디스플레이 검색" aria-label="디스플레이 검색" value="${esc(search)}"></label></div><div id="listGrid" class="screen-grid"></div>`;
 const update=()=>{destroyPlayers();releaseStages($('listGrid'));const filtered=screens.filter(s=>(!category||s.type===category)&&(category||listFilter==='all'||s.type===listFilter)&&s.name.toLowerCase().includes(search.toLowerCase()));$('listGrid').innerHTML=filtered.map(card).join('')||empty(search?'검색 결과가 없습니다.':'아직 등록된 디스플레이가 없습니다.');bindCards();bindAdd()};
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{listFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('active',n===b));update()});$('search').oninput=event=>{search=event.target.value;update()};$('library').onclick=()=>openMedia(null,null);bindAdd();update()}

function field(label,id,value,type='text',extra=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function infoPage(){const support=page==='support';const fields=support?[['문의 페이지 제목','contactTitle'],['이메일','email'],['전화번호','phone'],['운영 시간','hours']]:[['시스템 이름','systemName'],['사업장 이름','organization'],['설치 위치','location']];$('main').innerHTML=head(support?'문의 안내와 연락처를 직접 편집하세요.':'시스템 상태와 사업장 정보를 확인하고 관리하세요.')+`<div class="two-col"><form id="infoForm" class="panel"><div class="panel-title">${icon('edit')}<h2>${support?'문의 안내 편집':'사업장 정보 편집'}</h2></div><div class="note" style="margin-bottom:20px">${support?'현재 연락처와 문구는 편집용 예시입니다. 실제 문의는 전송되지 않습니다.':'사업장 정보는 예시입니다. 아래에서 변경한 내용은 서버에 저장됩니다.'}</div>${fields.map(([label,key])=>field(label,key,settings[key],'text','maxlength="3000"')).join('')}<label class="field">${support?'문의 안내 내용':'시스템 소개'}<textarea id="infoBody" maxlength="3000" rows="5">${esc(settings[support?'contactBody':'description'])}</textarea></label><button class="btn primary" type="submit">${icon('save')}변경사항 저장</button></form><div>${support?`<section class="contact-preview"><div class="kicker">CONTACT & SUPPORT</div><h2 id="contactPreviewTitle"></h2><p id="contactPreviewBody"></p><div class="contact-line">${icon('mail')}<span id="preview-email"></span></div><div class="contact-line">${icon('phone')}<span id="preview-phone"></span></div><div class="contact-line">${icon('clock')}<span id="preview-hours"></span></div><p style="margin-top:20px;font-size:10px">안내 페이지 미리보기 · 문의 전송 기능 없음</p></section>`:`<section class="panel"><div class="panel-title">${icon('server')}<h2>실제 실행 환경</h2></div>${[['애플리케이션',system.version],['운영체제',system.os],['Python',system.python],['서버 가동 시간',Math.floor(system.uptime/60)+'분'],['접속 범위',system.access],['미디어 저장량',(system.storageBytes/1024/1024).toFixed(2)+' MB']].map(([k,v])=>`<div class="info-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<div class="note" style="margin-top:20px">이 영역은 서버에서 읽은 실제 정보입니다. 위 사업장 정보와 구분하여 표시합니다.</div></section>`}</div></div>`;
 const preview=()=>{if(!support)return;$('contactPreviewTitle').textContent=$('contactTitle').value;$('contactPreviewBody').textContent=$('infoBody').value;for(const key of ['email','phone','hours'])$('preview-'+key).textContent=$(key).value};$('infoForm').oninput=()=>{dirty=true;preview()};$('infoForm').onsubmit=handle(async event=>{event.preventDefault();const body={revision:settings.revision};for(const [,key]of fields)body[key]=$(key).value;body[support?'contactBody':'description']=$('infoBody').value;settings=await api('/api/settings','PATCH',body);dirty=false;toast('정보가 저장되었습니다.');preview()});preview()}
async function refresh(){screens=(await api('/api/screens')).screens;render()}
function render(){destroyPlayers();previewPlayer?.destroy();previewPlayer=null;releaseStages($('main'));$('main').className=page==='editor'?'editor-page':'';const epoch=navEpoch;const active=()=>navEpoch===epoch;({playlists:()=>mountOperations($('main'),{api,handle,toast,showDialog,screens,media,page,isActive:active}),groups:()=>mountOperations($('main'),{api,handle,toast,showDialog,screens,media,page,isActive:active}),schedules:()=>mountOperations($('main'),{api,handle,toast,showDialog,screens,media,page,isActive:active}),reports:()=>mountOperations($('main'),{api,handle,toast,showDialog,screens,media,page,isActive:active}),devices:()=>mountDevices($('main'),{api,handle,toast,showDialog,screens,isActive:active}),registration:()=>mountRegistration($('main'),{api,handle,toast,isActive:active}),dashboard,screens:listing,ads:listing,menus:listing,system:infoPage,support:infoPage,editor,media:mediaPage,templates:templatesPage})[page]();if(page==='system')mainScreenSettings()}
function routeKey(){return page+(params.size?'?'+params.toString():'')}
function parkRoute(){scrollPositions.set(routeKey(),window.scrollY);if(page==='editor'&&draft)workspaces.set(routeKey(),{draft:clone(draft),slideIndex,selectedElement,selectionIds:[...selectionIds],undoStack:clone(undoStack),redoStack:clone(redoStack),dirty,editorKind,activeTemplateId});if(['system','support'].includes(page)&&$('infoForm'))formWorkspaces.set(page,{dirty,values:Object.fromEntries([...$('infoForm').querySelectorAll('input,textarea')].map(n=>[n.id,n.value]))})}
async function navigate(value,{push=true}={}){const next=readRoute(value),nextKey=next.page+(next.params.size?'?'+next.params.toString():'');if(nextKey===routeKey())return;parkRoute();rememberNav();const epoch=++navEpoch;document.querySelectorAll('dialog[open]').forEach(d=>d.close());page=next.page;params=next.params;draft=null;dirty=false;selectedElement=null;selectionIds=new Set();undoStack=[];redoStack=[];if(page==='editor'){const cached=workspaces.get(nextKey);if(cached){({draft,slideIndex,selectedElement,undoStack,redoStack,dirty,editorKind,activeTemplateId}=clone(cached));selectionIds=new Set(cached.selectionIds)}}destroyPlayers();previewPlayer?.destroy();releaseStages($('main'));$('main').innerHTML='<div class="loading">탭을 불러오는 중…</div>';if(push)history.pushState(null,'','/#/'+page+(params.size?'?'+params.toString():''));updateShell();try{const [s,t,f,m,c,p]=await Promise.all([api('/api/screens'),api('/api/templates'),api('/api/fonts'),api('/api/media'),api('/api/settings'),api('/api/players')]);if(epoch!==navEpoch)return;screens=s.screens;savedTemplates=t.templates;customFonts=f.fonts;media=m.media;settings=c;connections=p.players;installCustomFonts(customFonts);render();restoreForm();requestAnimationFrame(()=>{if(epoch===navEpoch)window.scrollTo(0,scrollPositions.get(nextKey)||0)})}catch(error){if(epoch===navEpoch)toast(error.message)}}
function updateShell(){$('breadcrumb').textContent=pages[page][0];document.title=pages[page][0]+' · Nuvistage';document.querySelectorAll('#nav a').forEach(a=>{const target=readRoute(a.href).page,active=target===page||(page==='editor'&&target===(params.has('template')?'templates':'screens'));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.body.classList.remove('nav-open')}
function restoreForm(){const saved=formWorkspaces.get(page);if(!saved||!$('infoForm'))return;for(const [id,value]of Object.entries(saved.values))if($(id))$(id).value=value;$('infoForm').dispatchEvent(new Event('input'));dirty=saved.dirty}
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download')||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const url=new URL(a.href,location.origin),path=url.hash.startsWith('#/')?new URL(url.hash.slice(1),location.origin).pathname:url.pathname;if(url.origin===location.origin&&(path==='/'||pages[path.split('/')[1]])){event.preventDefault();navigate(url.href).catch(e=>toast(e.message))}});
window.addEventListener('popstate',()=>navigate(location.href,{push:false}));
// Media library: uploads stay on this local server. Selecting multiple items builds a playlist.
function openMedia(kind,callback){mediaKind=kind;mediaCallback=callback;mediaSelection=new Set();$('uploadStatus').textContent='';$('mediaUpload').accept=kind==='image'?'image/jpeg,image/png,image/webp':kind==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp,video/mp4,video/webm';renderMedia();$('mediaDialog').showModal()}
function renderMedia(){const list=media.filter(m=>!mediaKind||m.mime.startsWith(mediaKind+'/'));$('mediaGrid').innerHTML=list.map(m=>`<div class="media-tile"><button class="media-card" data-media="${m.id}" aria-pressed="${mediaSelection.has(m.id)}" style="${mediaSelection.has(m.id)?'outline:2px solid #5579ef;outline-offset:-2px':''}"><div class="media-thumb">${m.mime.startsWith('image/')?`<img src="${m.url}" alt="${esc(m.name)}" loading="lazy">`:icon('video')}</div><p>${mediaSelection.has(m.id)?'✓ ':''}${esc(m.name)}</p><small>${m.mime} · ${formatBytes(m.size)}</small></button><button class="media-delete" data-delete-media="${m.id}">삭제</button></div>`).join('')||'<p class="muted">아직 업로드한 미디어가 없습니다.</p>';
 document.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>{if(!mediaCallback){toast('콘텐츠 편집기에서 이 미디어를 삽입할 수 있습니다.');return}mediaSelection.has(b.dataset.media)?mediaSelection.delete(b.dataset.media):mediaSelection.add(b.dataset.media);renderMedia()});bindMediaDelete();
 $('mediaChoose')?.remove();if(mediaCallback){const choose=document.createElement('button');choose.id='mediaChoose';choose.className='btn primary';choose.style.marginTop='20px';choose.disabled=!mediaSelection.size||uploading;choose.textContent=`선택한 ${mediaSelection.size}개 삽입`;choose.onclick=()=>{const selected=media.filter(m=>mediaSelection.has(m.id));$('mediaDialog').close();mediaCallback(selected)};$('mediaDialog').append(choose)}}

$('mediaClose').onclick=()=>{if(uploading){toast('업로드 완료 후 닫을 수 있습니다.');return}$('mediaDialog').close()};
$('mediaDialog').addEventListener('cancel',event=>{if(uploading)event.preventDefault()});
$('mediaUpload').onchange=handle(async event=>{const files=[...event.target.files];if(!files.length)return;uploading=true;event.target.disabled=true;renderMedia();const failures=[];let count=0;try{for(const file of files){$('uploadStatus').textContent=`업로드 중 ${++count}/${files.length} · ${file.name}`;try{const r=await fetch('/api/media',{method:'POST',headers:{'Content-Type':file.type,'X-Filename':encodeURIComponent(file.name),'X-CSRF-Token':csrfToken},body:file});const result=await r.json();if(!r.ok)throw Error(result.error);media.push(result.media);if(mediaCallback&&(!mediaKind||result.media.mime.startsWith(mediaKind+'/')))mediaSelection.add(result.media.id)}catch(error){failures.push(file.name+': '+error.message)}}$('uploadStatus').textContent=failures.length?failures.join('\n'):`${files.length}개 파일 업로드 완료${mediaCallback?' · 선택한 파일을 삽입해 주세요.':''}`;}finally{uploading=false;event.target.disabled=false;event.target.value='';renderMedia()}});
// Editor state and history. Saved screen remains unchanged until explicit save.
function snapshot(){undoStack.push(clone(draft));if(undoStack.length>60)undoStack.shift();redoStack=[];markDirty()}
function currentSlide(){return draft.content.slides[slideIndex]}
function selected(){return currentSlide()?.elements.find(e=>e.id===selectedElement)}
function replaceMode(mode){if(draft.content.mode===mode)return;snapshot();draft.content=switchContentMode(draft.content,mode);slideIndex=0;selectedElement=null;selectionIds.clear();editor();toast('모드별 작업을 보관했습니다. 이전 모드로 돌아가면 그대로 복원됩니다.')}
function editor(){destroyPlayers();releaseStages($('main'));previewPlayer?.destroy();previewPlayer=null;if(!draft){const tid=params.get('template');editorKind=tid?'template':'screen';activeTemplateId=tid&&!tid.startsWith('new-')?tid:null;const id=params.get('id');const item=activeTemplateId?savedTemplates.find(t=>t.id===activeTemplateId):null;const s=item?{...templateDraft(item),id:'template-'+item.id,revision:item.revision||1,name:item.name,status:'active',location:''}:screens.find(s=>s.id===id);if(!s){$('main').innerHTML=head('화면을 찾을 수 없습니다.')+'<a class="btn" href="/screens">디스플레이 목록으로</a>';return}draft=clone(s);draft.content ||= newContent('slides');if(draft.content.mode==='basic'){draft.content=newContent('slides');const legacy=newSlide();legacy.elements=[newElement('text',{text:draft.title,x:8,y:30,w:84,h:22,fontSize:90,color:draft.accent}),newElement('text',{text:draft.subtitle,x:8,y:58,w:84,h:20,fontSize:40,bold:false})];draft.content.slides=[legacy];markDirty()}}
 const c=draft.content;
 $('main').className='editor-page';$('main').innerHTML=`<div class="page-head"><div class="editor-heading"><a href="${editorKind==='template'?'/templates':'/screens'}" class="icon-btn" aria-label="목록으로">${icon('screen')}</a><div><div class="kicker">CONTENT STUDIO</div><h1>${esc(draft.name)} <button class="card-rename" id="editScreenName" aria-label="이름 변경">${icon('edit')}</button></h1><span class="save-state ${dirty?'dirty':''}" id="saveState">${dirty?'● 저장하지 않은 변경사항':'✓ 저장된 콘텐츠'}</span></div></div><div class="actions">${editorKind==='template'?'':`<a class="btn" href="/display.html?id=${draft.id}" target="_blank" rel="noopener">${icon('external')}출력 열기</a>`}${button('템플릿','openTemplates','layers')}${button(editorKind==='template'?'템플릿 저장':'저장 및 적용','save','save','primary')}</div></div>
 <details class="panel" style="padding:16px 20px;margin-bottom:20px"><summary style="cursor:pointer;font-size:12px;font-weight:650;color:#6d7c99">화면 기본 설정 · ${types[draft.type]}</summary><div class="field-row" style="margin-top:20px">${field(editorKind==='template'?'템플릿 이름':'디스플레이 이름','screenName',draft.name,'text','maxlength="100"')}${editorKind==='template'?'':field('설치 위치 / 기기 설명','screenLocation',draft.location||'','text','maxlength="100"')}<label class="field">화면 유형<select id="screenType">${Object.entries(types).filter(([v])=>editorKind!=='template'||v==='ads'||v==='menu').map(([v,t])=>`<option value="${v}" ${v===draft.type?'selected':''}>${t}</option>`).join('')}</select></label>${field('화면 제목','screenTitle',draft.title,'text','maxlength="100"')}${field('테마 색상','screenAccent',draft.accent,'color')}</div><label class="field">내용 / 안내 문구<textarea id="screenSubtitle" maxlength="1000">${esc(draft.subtitle)}</textarea></label><div class="field-row"><label class="field">출력 상태<select id="screenStatus"><option value="active" ${draft.status==='active'?'selected':''}>출력 활성</option><option value="paused" ${draft.status==='paused'?'selected':''}>일시 정지</option></select></label><label class="field">화면 방향<select id="screenAspect"><option value="landscape" ${c.aspect==='landscape'?'selected':''}>가로 · 16:9</option><option value="portrait" ${c.aspect==='portrait'?'selected':''}>세로 · 9:16</option></select></label></div></details>
 <div class="mode-tabs" role="group" aria-label="편집 모드">${[['slides','자유 편집'],['images','이미지 반복'],['videos','영상 반복'],...(draft.type==='menu'?[['menu','메뉴 템플릿']]:[])].map(([mode,t])=>`<button class="mode-tab ${c.mode===mode?'active':''}" data-mode="${mode}">${t}</button>`).join('')}</div>${c.mode==='menu'?menuEditor():compositionEditor()}
 <div class="editor-bottom"><p>${icon('check')} ${editorKind==='template'?'저장한 템플릿은 내 템플릿에서 다시 수정하거나 화면으로 만들 수 있습니다.':'저장 및 적용을 누르면 대시보드와 출력 화면에 반영됩니다.'}<br>편집 중인 변경사항은 저장 전까지 출력되지 않습니다.</p><button class="btn danger" id="deleteScreen">${icon('trash')}${editorKind==='template'?'템플릿 삭제':'디스플레이 삭제'}</button></div>`;
 bindBase();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>replaceMode(b.dataset.mode));if(c.mode==='menu')bindMenu();else bindComposition();
}
async function saveEditor(){if(!draft)return;if(editorKind==='template'){const body={};for(const key of ['name','type','title','subtitle','accent','content'])body[key]=draft[key];if(activeTemplateId)body.revision=draft.revision;const result=await api(activeTemplateId?'/api/templates/'+activeTemplateId:'/api/templates',activeTemplateId?'PATCH':'POST',body);const previous=routeKey();activeTemplateId=result.template.id;params=new URLSearchParams({template:activeTemplateId});history.replaceState(null,'','/#/editor?template='+activeTemplateId);workspaces.delete(previous);draft.revision=result.template.revision;savedTemplates=savedTemplates.filter(t=>t.id!==activeTemplateId);savedTemplates.push(result.template);templateCategory='mine';toast('내 템플릿에 저장했습니다.')}else{const body={};for(const key of ['name','type','title','subtitle','accent','status','content','location'])body[key]=draft[key]??'';body.revision=draft.revision;const result=await api('/api/screens/'+draft.id,'PATCH',body);draft=result.screen;screens=screens.map(s=>s.id===draft.id?clone(draft):s);toast('저장 완료 · 선택한 출력 모드가 화면에 반영됩니다.')}dirty=false;undoStack=[];redoStack=[];workspaces.set(routeKey(),{draft:clone(draft),slideIndex,selectedElement,selectionIds:[...selectionIds],undoStack:[],redoStack:[],dirty:false,editorKind,activeTemplateId});editor()}
function bindBase(){$('openTemplates').onclick=openTemplates;$('editScreenName').onclick=()=>editorKind==='template'?(($('screenName').closest('details').open=true),$('screenName').focus()):openScreenDialog(draft,true);for(const [id,key]of [['screenName','name'],['screenLocation','location'],['screenTitle','title'],['screenSubtitle','subtitle'],['screenAccent','accent'],['screenStatus','status']])if($(id))$(id).oninput=event=>{snapshot();draft[key]=event.target.value;redraw()};$('screenAspect').onchange=event=>{snapshot();draft.content.aspect=event.target.value;redraw()};$('screenType').onchange=event=>{snapshot();draft.type=event.target.value;editor()};$('save').onclick=handle(saveEditor);$('deleteScreen').onclick=handle(async()=>{if(editorKind==='template'){if(!await confirmDelete(draft.name,{template:true}))return;if(activeTemplateId){await api('/api/templates/'+activeTemplateId,'DELETE',{});savedTemplates=savedTemplates.filter(t=>t.id!==activeTemplateId)}workspaces.delete(routeKey());dirty=false;draft=null;await navigate('/templates');return}if(!confirm('이 출력 화면을 삭제할까요?'))return;await api('/api/screens/'+draft.id,'DELETE',{revision:draft.revision});workspaces.delete(routeKey());dirty=false;draft=null;await navigate('/screens')})}

function compositionEditor(){const c=draft.content,s=currentSlide();return `<div class="editor-layout"><aside class="slides-panel"><div class="pane-label">SLIDES <span>${c.slides.length}/50</span></div><div id="slidesList"></div><button class="btn slides-add" id="addSlide">${icon('plus')}${c.mode==='images'?'이미지 추가':c.mode==='videos'?'영상 추가':'슬라이드 추가'}</button>${c.mode==='slides'?'<button class="slides-add-blank" id="addBlankSlide">빈 슬라이드</button>':''}</aside><div class="editor-center"><div class="editor-toolbar">${button('텍스트','addText','text')}${button('도형','addShape','shape')}${button('이미지','addImage','image')}${button('영상','addVideo','video')}<span class="toolbar-divider"></span><button class="icon-btn" id="undo" aria-label="실행 취소" title="실행 취소 (⌘Z)">${icon('undo')}</button><button class="icon-btn" id="redo" aria-label="다시 실행" title="다시 실행 (⌘⇧Z)">${icon('redo')}</button><span class="toolbar-divider"></span>${button('미리보기','preview','play')}</div><div class="canvas-workspace"><div class="canvas-wrap ${c.aspect==='portrait'?'portrait-wrap':''}" id="canvasWrap"><div class="stage editor-stage" id="editorStage" aria-label="콘텐츠 편집 캔버스"></div></div></div><div class="editor-statusbar"><span>${c.aspect==='portrait'?'900 × 1600':'1600 × 900'} · ${types[draft.type]}</span><span id="slideStatus"></span><span>요소를 드래그하여 배치 · 우측 아래에서 크기 조절</span></div></div><aside class="properties-panel" id="properties"></aside></div>`}
function drawSlides(){if(!$('slidesList'))return;releaseStages($('slidesList'));$('slidesList').innerHTML=draft.content.slides.map((s,i)=>`<div class="slide-item ${slideIndex===i?'selected':''}" data-slide="${i}" tabindex="0" role="button" aria-label="슬라이드 ${i+1} 선택"><div class="stage" id="slidePreview-${i}"></div><div class="slide-label"><span>${String(i+1).padStart(2,'0')} · ${s.duration===0?'끝까지':s.duration+'초'}</span><span class="slide-buttons"><button data-shift="${i}" data-dir="-1" title="앞으로" aria-label="슬라이드 ${i+1} 앞으로">${icon('up')}</button><button data-shift="${i}" data-dir="1" title="뒤로" aria-label="슬라이드 ${i+1} 뒤로">${icon('down')}</button></span></div><small class="slide-template-name">${esc(s.templateName||'직접 편집')}</small></div>`).join('');draft.content.slides.forEach((s,i)=>drawStage($('slidePreview-'+i),{...draft,status:'active'},media,i));document.querySelectorAll('[data-slide]').forEach(b=>{b.onclick=()=>{slideIndex=Number(b.dataset.slide);selectedElement=null;redraw();drawProperties()};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}}});document.querySelectorAll('[data-shift]').forEach(b=>b.onclick=event=>{event.stopPropagation();const index=Number(b.dataset.shift),target=index+Number(b.dataset.dir);if(target<0||target>=draft.content.slides.length)return;snapshot();const slides=draft.content.slides;[slides[index],slides[target]]=[slides[target],slides[index]];slideIndex=target;selectedElement=null;redraw();drawProperties()})}
function redraw(){previewPlayer?.destroy();previewPlayer=null;if($('preview'))$('preview').innerHTML=icon('play')+'미리보기';if($('editorStage')){if(selectedElement&&!selectionIds.has(selectedElement))selectionIds=new Set([selectedElement]);if(!selectedElement)selectionIds.clear();drawStage($('editorStage'),draft,media,slideIndex,{editor:true});$('canvasWrap').classList.toggle('portrait-wrap',draft.content.aspect==='portrait');paintSelection(studioContext());$('slideStatus').textContent=draft.content.slides.length?`${slideIndex+1} / ${draft.content.slides.length} 슬라이드`:'미디어 또는 슬라이드를 추가하세요.';drawSlides()}if($('menuPreview'))drawStage($('menuPreview'),draft,media);if($('undo'))$('undo').disabled=!undoStack.length;if($('redo'))$('redo').disabled=!redoStack.length}
function studioContext(){return {draft:()=>draft,slide:currentSlide,elements:()=>currentSlide()?.elements.filter(e=>selectionIds.has(e.id))||[],getSelection:()=>new Set(selectionIds),setSelection:(ids)=>{selectionIds=new Set(ids);selectedElement=[...selectionIds][0]||null},snapshot,markDirty,redraw,properties:drawProperties,toast,showDialog,undo,redo,save:()=>$('save')?.click(),remove:deleteElement,getZoom:()=>editorZoom,setZoom:v=>editorZoom=v,getSnap:()=>editorSnap,setSnap:v=>editorSnap=v,getGrid:()=>editorGrid,setGrid:v=>editorGrid=v,fonts:()=>fontDialog(),addShape:shape=>{if((currentSlide()?.elements.length||0)>=40)return toast('요소는 최대 40개입니다.');snapshot();const element=newElement('shape',{x:20,y:25,w:35,h:shape==='line'?3:35,shape,color:draft.accent,strokeWidth:shape==='line'?4:0});ensureSlide().elements.push(element);selectedElement=element.id;selectionIds=new Set([element.id]);redraw();drawProperties()}}}
function fontDialog(){openFontManager({api,csrfToken,handle,toast,showDialog,getFonts:()=>customFonts,setFonts:f=>customFonts=f,useFont:id=>{if(!draft)return;snapshot();const chosen=currentSlide()?.elements.filter(e=>selectionIds.has(e.id)&&e.kind==='text'&&!e.locked)||[];if(chosen.length)chosen.forEach(e=>e.fontFamily=id);else{draft.content.fontFamily=id;if(currentSlide())currentSlide().fontFamily=id}redraw();drawProperties();toast('선택한 글꼴을 적용했습니다.')},isFontInDraft:id=>[draft,...[...workspaces.values()].map(w=>w.draft)].filter(Boolean).some(d=>[d.content,...Object.values(d.content?.modeDrafts||{})].some(c=>fontsFor({content:c}).includes(id)))})}

function bindComposition(){const c=draft.content;for(const id of ['addText','addShape','addImage','addVideo'])$(id).disabled=c.mode==='basic'||c.mode==='images'||c.mode==='videos';if(c.mode==='basic')$('addSlide').disabled=true;
 const append=blank=>{if(c.slides.length>=50){toast('슬라이드는 최대 50개입니다.');return}snapshot();c.slides.push(blank?newSlide():cloneSlideDesign(currentSlide(),c.background));slideIndex=c.slides.length-1;selectedElement=null;redraw();drawProperties()};
 $('addSlide').onclick=()=>{if(c.mode==='images'||c.mode==='videos'){openMedia(c.mode==='images'?'image':'video',insertMedia);return}append(false)};if($('addBlankSlide'))$('addBlankSlide').onclick=()=>append(true);

 $('addText').onclick=()=>addElement('text');$('addShape').onclick=()=>addElement('shape');$('addImage').onclick=()=>openMedia('image',insertMedia);$('addVideo').onclick=()=>openMedia('video',insertMedia);$('undo').onclick=undo;$('redo').onclick=redo;
 $('preview').onclick=()=>{if(previewPlayer){redraw();return}previewPlayer=new Playback($('editorStage'),{...draft,status:'active'},media,{startIndex:slideIndex});$('preview').innerHTML=icon('pause')+'편집으로'};enhanceToolbar(studioContext());redraw();drawProperties()}
function ensureSlide(){if(!currentSlide()){const s=newSlide();draft.content.slides.push(s);slideIndex=draft.content.slides.length-1}return currentSlide()}
function addElement(kind){if((currentSlide()?.elements.length||0)>=40){toast('요소는 최대 40개입니다.');return}snapshot();const s=ensureSlide();const e=newElement(kind,kind==='shape'?{x:15,y:40,w:50,h:25,color:draft.accent}:{});s.elements.push(e);selectedElement=e.id;redraw();drawProperties()}
function insertMedia(items){const c=draft.content,simple=['images','videos'].includes(c.mode);if(simple&&c.slides.length+items.length>50){toast('슬라이드는 최대 50개입니다.');return}if(!simple&&(currentSlide()?.elements.length||0)+items.length>40){toast('슬라이드 요소는 최대 40개입니다.');return}snapshot();for(const m of items){const e=newElement(m.mime.startsWith('image/')?'image':'video',{x:simple?0:10,y:simple?0:10,w:simple?100:65,h:simple?100:65,mediaId:m.id});if(simple){const s=newSlide();s.duration=e.kind==='video'?0:8;s.elements=[e];c.slides.push(s);slideIndex=c.slides.length-1}else ensureSlide().elements.push(e);selectedElement=e.id}redraw();drawProperties()}
function drawProperties(){const host=$('properties');if(!host)return;const c=draft.content,s=currentSlide(),e=selected();host.innerHTML=`<section><div class="pane-label">${e?'ELEMENT PROPERTIES':'SLIDE SETTINGS'}</div>${e?`<h3>${({text:'텍스트',shape:'도형',image:'이미지',video:'영상'})[e.kind]}</h3>${e.kind==='text'?`<label class="field">텍스트<textarea id="propText" maxlength="3000">${esc(e.text)}</textarea></label>`:''}<div class="field-row">${field('X (%)','propX',e.x,'number','min="0" max="99" step="0.1"')}${field('Y (%)','propY',e.y,'number','min="0" max="99" step="0.1"')}${field('너비 (%)','propW',e.w,'number','min="0.1" max="100" step="0.1"')}${field('높이 (%)','propH',e.h,'number','min="0.1" max="100" step="0.1"')}</div>${['text','shape'].includes(e.kind)?field(e.kind==='text'?'글자 색상':'도형 색상','propColor',e.color,'color'):''}${e.kind==='text'?`${field('글자 크기 (디자인 px)','propFont',e.fontSize,'number','min="8" max="180"')}<label class="field">정렬<select id="propAlign">${[['left','왼쪽'],['center','가운데'],['right','오른쪽']].map(([v,t])=>`<option value="${v}" ${e.align===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><input id="propBold" type="checkbox" ${e.bold?'checked':''}>굵은 글씨</label>`:''}${['image','video'].includes(e.kind)?`<label class="field">미디어 맞춤<select id="propFit"><option value="cover" ${e.fit==='cover'?'selected':''}>화면 채우기</option><option value="contain" ${e.fit==='contain'?'selected':''}>전체 보이기</option></select></label>`:''}${elementExtraControls(e)}<div class="actions">${button('복제','duplicateElement','copy')}${button('삭제','deleteElement','trash','danger')}</div><div class="actions" style="margin-top:8px">${button('앞으로','forwardElement','up')}${button('뒤로','backwardElement','down')}</div>`:`<p class="muted" style="margin-bottom:15px">${c.mode==='basic'?'기본 설정에서 제목과 내용을 편집하세요.':'캔버스의 요소를 선택해 속성을 편집하세요.'}</p>`}
 </section><section class="prop-section"><h3>화면과 재생</h3>${field(s?'이 슬라이드 배경색':'배경색','background',s?.background||c.background,'color')}${s?`${field('표시 시간 (초 · 영상은 0 = 끝까지)','duration',s.duration,'number','min="0" max="3600" step="0.5"')}<label class="field">전환 애니메이션<select id="transition">${[['none','없음'],['fade','페이드'],['slide','슬라이드'],['zoom','줌']].map(([v,t])=>`<option value="${v}" ${s.transition===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<label class="field">영상 재생 배속<select id="playbackRate">${[.25,.5,.75,1,1.25,1.5,2,3,4].map(n=>`<option value="${n}" ${c.playbackRate===n?'selected':''}>${n}×</option>`).join('')}</select></label>${s?`<div class="actions">${button('슬라이드 복제','duplicateSlide','copy')}${button('삭제','deleteSlide','trash','danger')}</div>`:''}${c.mode==='slides'?`<label class="field" style="margin-top:18px">이 슬라이드의 템플릿<select id="template"><option value="">템플릿 선택…</option>${[...BUILTIN_TEMPLATES,...savedTemplates].filter(t=>t.type===(draft.type==='notice'?'ads':draft.type)).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>`:''}</section>${s?`<section class="prop-section"><h3>레이어 <span class="count">${s.elements.length}</span></h3><div class="layers">${[...s.elements].reverse().map(e=>`<button class="layer ${e.id===selectedElement?'active':''}" data-layer="${esc(e.id)}">${icon(e.kind)}<span>${esc(e.text||({image:'이미지',video:'영상',shape:'도형'})[e.kind])}</span></button>`).join('')||'<p class="muted">요소를 추가해 주세요.</p>'}</div></section>`:''}`;
 const bind=(id,fn)=>{if($(id))$(id).oninput=event=>{snapshot();fn(event.target);redraw()}};
 bind('background',t=>{if(s)s.background=t.value;else c.background=t.value});bind('duration',t=>s.duration=Math.min(3600,Math.max(0,Number(t.value))));bind('transition',t=>s.transition=t.value);bind('playbackRate',t=>c.playbackRate=Number(t.value));
 if(e){bindElementExtras(e,bind);bind('propText',t=>e.text=t.value);bind('propColor',t=>e.color=t.value);bind('propFont',t=>e.fontSize=Math.max(8,Math.min(180,Number(t.value))));bind('propAlign',t=>e.align=t.value);bind('propBold',t=>e.bold=t.checked);bind('propFit',t=>e.fit=t.value);for(const [id,k]of [['propX','x'],['propY','y'],['propW','w'],['propH','h']])bind(id,t=>{const n=Number(t.value);if(k==='x')e.x=Math.max(0,Math.min(100-e.w,n));if(k==='y')e.y=Math.max(0,Math.min(100-e.h,n));if(k==='w')e.w=Math.max(.1,Math.min(100-e.x,n));if(k==='h')e.h=Math.max(.1,Math.min(100-e.y,n))});$('deleteElement').onclick=deleteElement;$('duplicateElement').onclick=()=>{if(s.elements.length>=40){toast('요소는 최대 40개입니다.');return}snapshot();const copy={...clone(e),id:uid(),x:Math.min(100-e.w,e.x+2),y:Math.min(100-e.h,e.y+2)};s.elements.push(copy);selectedElement=copy.id;redraw();drawProperties()};for(const [id,delta]of [['forwardElement',1],['backwardElement',-1]])$(id).onclick=()=>{const i=s.elements.indexOf(e),j=i+delta;if(j<0||j>=s.elements.length)return;snapshot();[s.elements[i],s.elements[j]]=[s.elements[j],s.elements[i]];redraw();drawProperties()}}
 if(s){$('duplicateSlide').onclick=()=>{if(c.slides.length>=50){toast('슬라이드는 최대 50개입니다.');return}snapshot();const copy=clone(s);copy.id=uid();copy.elements.forEach(e=>e.id=uid());c.slides.splice(slideIndex+1,0,copy);slideIndex++;selectedElement=null;redraw();drawProperties()};$('deleteSlide').onclick=()=>{snapshot();c.slides.splice(slideIndex,1);slideIndex=Math.max(0,slideIndex-1);selectedElement=null;redraw();drawProperties()}}
 document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{selectedElement=b.dataset.layer;redraw();drawProperties()});if($('template'))$('template').onchange=handle(event=>applyTemplate(event.target.value));enhanceInspector(studioContext())
}
function deleteElement(){const s=currentSlide();if(!s)return;const ids=new Set([...selectionIds].filter(id=>!s.elements.find(e=>e.id===id)?.locked));if(!ids.size)return;snapshot();s.elements=s.elements.filter(e=>!ids.has(e.id));selectionIds.clear();selectedElement=null;redraw();drawProperties()}

function dragElement(event,node){if(event.button!==0)return;event.stopPropagation();event.preventDefault();selectedElement=node.dataset.element;const e=selected();if(!e)return;const resize=event.target.classList.contains('resize-handle'),rect=$('editorStage').getBoundingClientRect(),start={...clone(e),clientX:event.clientX,clientY:event.clientY};node.setPointerCapture(event.pointerId);node.classList.add('selected');let moved=false;
 const move=event=>{if(!moved){snapshot();moved=true}const dx=(event.clientX-start.clientX)/rect.width*100,dy=(event.clientY-start.clientY)/rect.height*100;if(resize){e.w=Math.max(.1,Math.min(100-e.x,start.w+dx));e.h=Math.max(.1,Math.min(100-e.y,start.h+dy))}else{e.x=Math.max(0,Math.min(100-e.w,start.x+dx));e.y=Math.max(0,Math.min(100-e.h,start.y+dy))}for(const k of ['x','y','w','h'])e[k]=Math.round(e[k]*10)/10;$('editorStage').querySelectorAll('[data-element]').forEach(n=>{if(n.dataset.element===e.id)Object.assign(n.style,{left:e.x+'%',top:e.y+'%',width:e.w+'%',height:e.h+'%'})})};
 const up=()=>{node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',up);redraw();drawProperties()};node.addEventListener('pointermove',move);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',up)
}
function undo(){if(!undoStack.length)return;redoStack.push(clone(draft));draft=undoStack.pop();slideIndex=Math.min(slideIndex,Math.max(0,draft.content.slides.length-1));selectedElement=null;markDirty();editor()}
function redo(){if(!redoStack.length)return;undoStack.push(clone(draft));draft=redoStack.pop();slideIndex=Math.min(slideIndex,Math.max(0,draft.content.slides.length-1));selectedElement=null;markDirty();editor()}
window.addEventListener('keydown',event=>studioKeyboard(event,page==='editor'&&draft?studioContext():null));
function applyTemplate(kind){const template=BUILTIN_TEMPLATES.find(t=>t.id===kind||t.id==='builtin-'+kind)||savedTemplates.find(t=>t.id===kind);if(template)loadTemplate(template,'slide')}

function menuEditor(){return `<div class="two-col"><section class="panel"><div class="panel-title">${icon('menu')}<h2>메뉴 구성 <span class="count">${draft.content.menuItems.length}/16</span></h2></div><div id="menuRows"></div>${button('메뉴 추가','addMenu','plus','subtle')}</section><div class="menu-editor-preview"><section class="panel"><div class="pane-label">LIVE PREVIEW <span>저장 전 미리보기</span></div><div id="menuPreview" class="stage"></div>${field('배경색','menuBackground',draft.content.background,'color')}<p class="muted">메뉴 이름 · 가격 · 설명 · 추천 · 품절 상태를 편집하세요.<br>사진을 자유롭게 배치하려면 ‘자유 편집’ 모드를 이용하세요.</p></section></div></div>`}
function bindMenu(){const c=draft.content;const rows=()=>{$('menuRows').innerHTML=c.menuItems.map((item,i)=>`<div class="menu-edit-row">${field('메뉴 이름','menuName-'+i,item.name,'text','maxlength="80"')}${field('가격','menuPrice-'+i,item.price,'text','maxlength="40"')}<label class="field wide">설명<input id="menuDesc-${i}" value="${esc(item.description)}" maxlength="200"></label><div class="menu-edit-flags"><label><input type="checkbox" id="menuFeatured-${i}" ${item.featured?'checked':''}>추천 메뉴</label><label><input type="checkbox" id="menuSold-${i}" ${item.soldOut?'checked':''}>품절</label><button class="icon-btn" data-remove-menu="${i}" aria-label="${i+1}번 메뉴 삭제">${icon('trash')}</button></div></div>`).join('');c.menuItems.forEach((item,i)=>{for(const [prefix,key]of [['menuName','name'],['menuPrice','price'],['menuDesc','description'],['menuFeatured','featured'],['menuSold','soldOut']])$(prefix+'-'+i).oninput=event=>{snapshot();item[key]=event.target.type==='checkbox'?event.target.checked:event.target.value;redraw()}});document.querySelectorAll('[data-remove-menu]').forEach(b=>b.onclick=()=>{snapshot();c.menuItems.splice(Number(b.dataset.removeMenu),1);rows();redraw()})};rows();$('addMenu').onclick=()=>{if(c.menuItems.length>=16){toast('메뉴는 최대 16개입니다.');return}snapshot();c.menuItems.push({name:'새 메뉴',price:'4,500원',description:'',soldOut:false,featured:false});rows();redraw()};$('menuBackground').oninput=event=>{snapshot();c.background=event.target.value;redraw()};redraw()}
function formatBytes(size){if(size<1024)return size+' B';if(size<1024**2)return (size/1024).toFixed(1)+' KB';if(size<1024**3)return (size/1024**2).toFixed(1)+' MB';return (size/1024**3).toFixed(2)+' GB'}
function bindConnections(){document.querySelectorAll('[data-connection]').forEach(node=>{const active=connections.filter(p=>p.screenId===node.dataset.connection&&p.online);node.classList.toggle('online',!!active.length);node.innerHTML='<span class="online-dot"></span>'+ (active.length?active.length+'개 플레이어 연결 중':'연결된 플레이어 없음')})}
function showDialog(title,body){const dialog=$('uiDialog');dialog.innerHTML=`<div class="dialog-head"><div><small>NUVISTAGE WORKSPACE</small><h2>${esc(title)}</h2></div><button class="icon-btn" id="dialogClose" aria-label="창 닫기">${icon('close')}</button></div>${body}`;$('dialogClose').onclick=()=>dialog.close();dialog.showModal();return dialog}
function openScreenDialog(screen=null,editingDraft=false){const type=screen?.type||({menus:'menu'})[page]||'ads';const dialog=showDialog(screen?'디스플레이 이름과 위치 변경':'새 디스플레이 추가',`<p class="muted">어떤 화면인지 쉽게 알아볼 수 있는 이름과 설치 위치를 입력하세요. 각 라즈베리파이는 생성한 화면의 연결 링크를 열면 됩니다.</p><form id="screenDialogForm" class="dialog-form">${field('화면 이름','dialogName',screen?.name||'','text','maxlength="100" required placeholder="예: 카운터 오른쪽 메뉴판"')}${field('설치 위치 / 기기 설명','dialogLocation',screen?.location||'','text','maxlength="100" placeholder="예: 1층 카운터 · Raspberry Pi 02"')}${screen?'':`<label class="field">화면 유형<select id="dialogType">${Object.entries(types).map(([v,t])=>`<option value="${v}" ${v===type?'selected':''}>${t}</option>`).join('')}</select></label>`}<p id="dialogError" class="form-error" role="alert"></p><div class="dialog-actions"><button type="submit" class="btn primary">${screen?'변경사항 저장':'화면 만들기'}</button></div></form>`);
 $('screenDialogForm').onsubmit=async event=>{event.preventDefault();const submit=event.currentTarget.querySelector('button[type=submit]');submit.disabled=true;$('dialogError').textContent='';try{const name=$('dialogName').value.trim(),locationName=$('dialogLocation').value.trim();if(!name)throw Error('화면 이름을 입력해 주세요.');if(editingDraft){snapshot();draft.name=name;draft.location=locationName;dialog.close();editor();return}if(screen){await api('/api/screens/'+screen.id,'PATCH',{name,location:locationName,revision:screen.revision});dialog.close();await refresh();toast('이름과 설치 위치를 변경했습니다.');return}const selectedType=$('dialogType').value;let body={name,location:locationName,type:selectedType};body.content=newContent('slides');const result=await api('/api/screens','POST',body);dialog.close();navigate('/editor?id='+result.screen.id)}catch(error){$('dialogError').textContent=error.message}finally{submit.disabled=false}};setTimeout(()=>$('dialogName')?.focus(),0)}
async function pairScreen(screen){const link=await api('/api/screens/'+screen.id+'/player-link');const dialog=showDialog('플레이어 연결 · '+screen.name,`<div class="note">메인 라즈베리파이 한 대에서만 서버를 실행합니다. 다른 라즈베리파이에서는 아래 링크를 Chromium 키오스크로 열어 주세요. 이 링크는 이 화면의 출력만 허용하며 관리자 기능에는 접근할 수 없습니다.</div><div style="margin-top:20px">${field('메인 서버 주소','pairBase',location.origin,'url','placeholder="http://192.168.0.10:8765"')}<p class="muted" style="margin-bottom:12px">다른 기기에서는 localhost 대신 메인 서버의 LAN IP를 입력하세요. 서버는 --host 0.0.0.0 옵션으로 실행해야 합니다.</p><div class="pair-url" id="pairUrl"></div></div><div class="actions" style="margin-top:18px">${button('연결 링크 복사','copyPair','copy')}${button('플레이어 설정 다운로드','downloadPair','save')}<a class="btn" id="openPair" target="_blank" rel="noopener">${icon('external')}출력 테스트</a></div><div class="prop-section"><p class="muted">기기 연결을 해제하려면 링크를 갱신하세요. 기존 링크로 연결된 모든 플레이어가 차단됩니다.</p><button class="btn danger" id="rotatePair" style="margin-top:10px">기존 연결 해제 및 링크 갱신</button></div>`);
 const url=()=>{const base=new URL($('pairBase').value);if(!['http:','https:'].includes(base.protocol)||base.username||base.password)throw Error('올바른 서버 주소를 입력해 주세요.');return base.origin+link.path};const update=()=>{try{$('pairUrl').textContent=url();$('openPair').href=url()}catch{$('pairUrl').textContent='서버 주소를 확인해 주세요.';$('openPair').removeAttribute('href')}};$('pairBase').oninput=update;update();$('copyPair').onclick=handle(async()=>{if(!navigator.clipboard){toast('아래 링크를 직접 선택해 복사해 주세요.');return}await navigator.clipboard.writeText(url());toast('플레이어 연결 링크를 복사했습니다.')});$('downloadPair').onclick=handle(()=>downloadJson({version:1,playerUrl:url(),screenName:screen.name},'nuvistage-player.json'));$('rotatePair').onclick=handle(async()=>{if(!confirm('기존 링크로 연결한 모든 플레이어를 해제하고 새 링크를 발급할까요?'))return;await api('/api/screens/'+screen.id+'/player-link','POST',{});dialog.close();await pairScreen(screen)})}
function downloadJson(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function mediaPage(){destroyPlayers();releaseStages($('main'));$('main').innerHTML=head('파일 크기·개수의 앱 제한 없이, 서버 디스크 공간 안에서 관리하세요.',button('파일 업로드','uploadMediaPage','plus','primary'))+`<div class="media-toolbar"><div class="capacity-note">${icon('layers')}<b>${media.length}개</b> · ${formatBytes(media.reduce((n,m)=>n+m.size,0))} 사용 중</div><p class="muted">화면이나 저장한 템플릿에서 사용 중인 파일은 먼저 참조를 해제해야 삭제할 수 있습니다.</p></div><div class="media-list">${media.map(m=>`<div class="media-tile"><a class="media-card" href="${m.url}" target="_blank" rel="noopener" style="display:block"><div class="media-thumb">${m.mime.startsWith('image/')?`<img src="${m.url}" alt="${esc(m.name)}" loading="lazy">`:icon('video')}</div><p>${esc(m.name)}</p><small>${m.mime} · ${formatBytes(m.size)}</small></a><button class="media-delete" data-delete-media="${m.id}">파일 삭제</button></div>`).join('')||'<section class="empty"><h3>미디어를 추가해 보세요.</h3><p>이미지와 영상을 업로드하면 모든 화면에서 재사용할 수 있습니다.</p></section>'}</div>`;$('uploadMediaPage').onclick=()=>openMedia(null,null);bindMediaDelete()}
function bindMediaDelete(){document.querySelectorAll('[data-delete-media]').forEach(b=>b.onclick=handle(async()=>{const item=media.find(m=>m.id===b.dataset.deleteMedia);if(!item||!confirm('“'+item.name+'” 파일을 삭제할까요? 이 작업은 되돌릴 수 없습니다.'))return;await api('/api/media/'+item.id,'DELETE',{});media=media.filter(m=>m.id!==item.id);mediaSelection.delete(item.id);if($('mediaDialog').open)renderMedia();else if(page==='media')mediaPage();toast('미디어 파일을 삭제했습니다.')}))}
$('mediaDialog').addEventListener('close',()=>{if(page==='media')mediaPage()});
function elementExtraControls(e){const a=e.animation||{preset:'none',duration:.8,delay:0,repeat:false};return `${e.kind==='text'?`<label class="field">글꼴<select id="propFamily">${[['sans','기본 (프리텐다드)'],...FONT_OPTIONS.map(([id,label])=>[id,label]),['serif','세리프 (나눔명조)'],['mono','고정 폭']].map(([v,t])=>`<option value="${v}" ${(e.fontFamily||'sans')===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="field-row">${field('줄 간격','propLineHeight',e.lineHeight||1.25,'number','min="0.8" max="2.5" step="0.05"')}${field('자간 (px)','propSpacing',e.letterSpacing||0,'number','min="-5" max="30" step="0.5"')}</div>`:''}<div class="field-row">${field('불투명도','propOpacity',e.opacity??1,'number','min="0" max="1" step="0.05"')}${e.kind!=='text'?field('모서리 (px)','propRadius',e.radius||0,'number','min="0" max="400"'):''}</div><div class="layer-animation"><label class="field">이 레이어의 애니메이션<select id="animPreset">${[['none','없음'],['fade','서서히 나타나기'],['rise','아래에서 올라오기'],['slide-left','왼쪽에서 들어오기'],['zoom','확대하며 나타나기'],['pulse','부드러운 펄스']].map(([v,t])=>`<option value="${v}" ${a.preset===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="field-row">${field('효과 시간 (초)','animDuration',a.duration,'number','min="0.1" max="10" step="0.1"')}${field('시작 지연 (초)','animDelay',a.delay,'number','min="0" max="30" step="0.1"')}</div><label class="field"><input type="checkbox" id="animRepeat" ${a.repeat?'checked':''}>효과 반복</label><label class="field">다음 페이지로 넘어갈 때<select id="animExit">${[['none','퇴장 효과 없음'],['reverse','진입 효과의 반대로 돌아가기'],['fade','서서히 사라지기'],['drop','아래로 내려가기'],['slide-right','오른쪽으로 나가기'],['zoom-out','축소하며 사라지기']].map(([v,t])=>`<option value="${v}" ${(a.exit||'none')===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="field-row">${field('퇴장 시간 (초)','animExitDuration',a.exitDuration||.6,'number','min="0.1" max="5" step="0.1"')}${field('퇴장 지연 (초)','animExitDelay',a.exitDelay||0,'number','min="0" max="10" step="0.1"')}</div><p class="muted" style="font-size:9px">퇴장 효과가 끝난 뒤 다음 슬라이드로 넘어갑니다. 편집 중에는 정지 상태로 보입니다. 미리보기에서 움직임을 확인하세요.</p></div>`}
function bindElementExtras(e,bind){bind('propFamily',t=>e.fontFamily=t.value);bind('propLineHeight',t=>e.lineHeight=Math.max(.8,Math.min(2.5,Number(t.value))));bind('propSpacing',t=>e.letterSpacing=Math.max(-5,Math.min(30,Number(t.value))));bind('propOpacity',t=>e.opacity=Math.max(0,Math.min(1,Number(t.value))));bind('propRadius',t=>e.radius=Math.max(0,Math.min(400,Number(t.value))));const anim=()=>e.animation||={preset:'none',duration:.8,delay:0,repeat:false};bind('animPreset',t=>anim().preset=t.value);bind('animDuration',t=>anim().duration=Math.max(.1,Math.min(10,Number(t.value))));bind('animDelay',t=>anim().delay=Math.max(0,Math.min(30,Number(t.value))));bind('animRepeat',t=>anim().repeat=t.checked);bind('animExit',t=>anim().exit=t.value);bind('animExitDuration',t=>anim().exitDuration=Math.max(.1,Math.min(5,Number(t.value))));bind('animExitDelay',t=>anim().exitDelay=Math.max(0,Math.min(10,Number(t.value))))}
let templateCategory='all',templateDomain='all';
const templateTypeLabel=type=>({ads:'광고판',menu:'메뉴판',})[type]||'광고판';
function templateCard(template,index,dialog=false){return `<article class="template-card"><div class="template-stage-wrap"><div class="stage" id="${dialog?'pick':'collection'}-template-${index}"></div></div><div class="template-body"><div class="template-type-label">${templateTypeLabel(template.type)} · ${template.builtin?'기본 디자인':'내 디자인'}</div><h3>${esc(template.name)}</h3><p>${esc(template.description||'직접 저장한 템플릿')} · ${template.content.aspect==='portrait'?'세로 9:16':'가로 16:9'}</p><div class="actions"><button class="btn primary" data-use-template="${template.id}">${dialog?'이 디자인 적용':'새 화면으로 만들기'}</button>${!template.builtin?`<button class="btn" data-edit-template="${template.id}">${icon('edit')}수정</button><button class="icon-btn" data-export-template="${template.id}" aria-label="${esc(template.name)} 내보내기">${icon('save')}</button><button class="icon-btn" data-remove-template="${template.id}" aria-label="${esc(template.name)} 삭제">${icon('trash')}</button>`:''}</div></div></article>`}
function templatesPage(){destroyPlayers();releaseStages($('main'));const source=templateCategory==='mine'?savedTemplates:templateCategory==='builtin'?BUILTIN_TEMPLATES:[...BUILTIN_TEMPLATES,...savedTemplates],templates=source.filter(t=>templateDomain==='all'||t.type===templateDomain);$('main').innerHTML=head('한국어 기본 디자인 31종 · 내 템플릿을 직접 만들고 수정할 수 있습니다.',`<button class="btn primary" id="createTemplate">${icon('plus')}템플릿 만들기</button><label class="btn template-import-label">${icon('plus')}템플릿 파일 불러오기<input id="importTemplate" type="file" accept="application/json,.json" style="display:none"></label>`)+`<div class="tabs template-domain-tabs">${[['all','전체 종류'],['menu','메뉴판 디자인'],['ads','광고판 디자인']].map(([v,t])=>`<button class="tab ${v===templateDomain?'active':''}" data-template-domain="${v}">${t}</button>`).join('')}</div><div class="tabs template-filter">${[['all','전체'],['builtin','기본 템플릿'],['mine','내 템플릿']].map(([v,t])=>`<button class="tab ${v===templateCategory?'active':''}" data-template-category="${v}">${t}</button>`).join('')}</div><div class="template-grid">${templates.map((t,i)=>templateCard(t,i)).join('')||'<div class="empty"><h3>나만의 템플릿을 만들어 보세요.</h3><p>빈 캔버스에서 텍스트·도형·이미지를 배치하고 재사용할 수 있습니다.</p><button class="btn primary" id="createBlankTemplate">빈 템플릿 만들기</button></div>'}</div>`;templates.forEach((t,i)=>drawStage($('collection-template-'+i),templatePreview(t),media));document.querySelectorAll('[data-template-category]').forEach(b=>b.onclick=()=>{templateCategory=b.dataset.templateCategory;templatesPage()});document.querySelectorAll('[data-template-domain]').forEach(b=>b.onclick=()=>{templateDomain=b.dataset.templateDomain;templatesPage()});bindTemplateButtons(false);$('importTemplate').onchange=importTemplate;$('createTemplate').onclick=createTemplate;if($('createBlankTemplate'))$('createBlankTemplate').onclick=createTemplate}
function openTemplates(){const dialog=$('templateDialog');releaseStages(dialog);const type=draft.type==='notice'?'ads':draft.type,pool=[...savedTemplates,...BUILTIN_TEMPLATES].filter(t=>t.type===type);dialog.innerHTML=`<div class="dialog-head"><div><small>${type==='menu'?'MENU DESIGNS':'AD DESIGNS'}</small><h2>${templateTypeLabel(type)} 템플릿</h2></div><button class="icon-btn" id="closeTemplates" aria-label="템플릿 창 닫기">${icon('close')}</button></div><div class="template-topbar">${button('내 디자인으로 저장','saveMyTemplate','save','primary')}<label class="btn template-import-label">${icon('plus')}JSON 불러오기<input id="importTemplate" type="file" accept="application/json,.json" style="display:none"></label></div><label class="template-scope">적용 범위<select id="templateScope"><option value="slide">현재 슬라이드에만 적용</option><option value="all">전체 구성 불러오기</option></select><span>다른 슬라이드는 그대로 유지됩니다. 새 슬라이드는 현재 디자인을 이어받습니다.</span></label><div class="template-grid">${pool.map((t,i)=>templateCard(t,i,true)).join('')}</div>`;pool.forEach((t,i)=>drawStage($('pick-template-'+i),templatePreview(t),media));$('closeTemplates').onclick=()=>dialog.close();$('saveMyTemplate').onclick=()=>{dialog.close();saveMyTemplate()};$('importTemplate').onchange=importTemplate;bindTemplateButtons(true);if(!dialog.open)dialog.showModal()}
$('templateDialog').addEventListener('close',()=>releaseStages($('templateDialog')));
function loadTemplate(template,scope){const result=applyDesign(draft,template,{index:slideIndex,scope:scope||$('templateScope')?.value||'slide'});snapshot();draft=result.screen;slideIndex=result.index;selectedElement=null;$('templateDialog').close();editor();toast('디자인을 적용했습니다. 저장 및 적용 전까지 실제 출력은 유지됩니다.')}

function bindTemplateButtons(dialog){document.querySelectorAll('[data-edit-template]').forEach(b=>b.onclick=()=>navigate('/editor?template='+b.dataset.editTemplate));const find=id=>[...BUILTIN_TEMPLATES,...savedTemplates].find(t=>t.id===id);document.querySelectorAll('[data-use-template]').forEach(b=>b.onclick=handle(async()=>{const template=find(b.dataset.useTemplate);if(dialog){loadTemplate(template);return}const body={name:template.name,...templateDraft(template)};const result=await api('/api/screens','POST',body);navigate('/editor?id='+result.screen.id)}));document.querySelectorAll('[data-export-template]').forEach(b=>b.onclick=()=>{const item=find(b.dataset.exportTemplate);downloadJson({format:'nuvistage-template',version:1,...item},item.name+'.json')});document.querySelectorAll('[data-remove-template]').forEach(b=>b.onclick=handle(async()=>{const item=find(b.dataset.removeTemplate);if(!await confirmDelete(item.name,{template:true}))return;await api('/api/templates/'+item.id,'DELETE',{});savedTemplates=savedTemplates.filter(t=>t.id!==item.id);for(const [key,w]of workspaces)if(w.activeTemplateId===item.id)workspaces.delete(key);dialog?openTemplates():templatesPage();toast('템플릿을 삭제했습니다.')}))}
function createTemplate(){const dialog=showDialog('새 템플릿 만들기',`<form id="createTemplateForm" class="dialog-form">${field('템플릿 이름','newTemplateName','나의 새 템플릿','text','required maxlength="100"')}<label class="field">템플릿 종류<select id="newTemplateType"><option value="ads">광고판</option><option value="menu">메뉴판</option></select></label><label class="field">화면 방향<select id="newTemplateAspect"><option value="landscape">가로 · 16:9</option><option value="portrait">세로 · 9:16</option></select></label><button class="btn primary" type="submit">빈 캔버스에서 만들기</button></form>`);$('createTemplateForm').onsubmit=event=>{event.preventDefault();const key='new-'+uid(),content=newContent('slides');content.aspect=$('newTemplateAspect').value;content.slides=[newSlide()];const model={id:'template-'+uid(),name:$('newTemplateName').value.trim(),type:$('newTemplateType').value,title:$('newTemplateName').value.trim(),subtitle:'',accent:'#6685ff',status:'active',location:'',revision:0,content};workspaces.set('editor?template='+key,{draft:model,slideIndex:0,selectedElement:null,selectionIds:[],undoStack:[],redoStack:[],dirty:true,editorKind:'template',activeTemplateId:null});dialog.close();navigate('/editor?template='+key)}}
function saveMyTemplate(){const dialog=showDialog('내 템플릿으로 저장',`<form id="templateNameForm" class="dialog-form">${field('템플릿 이름','templateName',draft.name+' 템플릿','text','required maxlength="100"')}${draft.content.mode==='slides'?'<label class="field">저장 범위<select id="templateSaveScope"><option value="slide">현재 슬라이드 디자인</option><option value="all">전체 슬라이드 구성</option></select></label>':''}<p class="muted">선택한 범위의 편집 콘텐츠를 저장합니다. 화면 이름과 설치 위치는 포함하지 않습니다. 이미지·영상은 같은 서버의 라이브러리를 참조합니다.</p><p id="templateSaveError" class="form-error"></p><div class="dialog-actions"><button class="btn primary" type="submit">템플릿 저장</button></div></form>`);$('templateNameForm').onsubmit=async event=>{event.preventDefault();const submit=event.currentTarget.querySelector('button');submit.disabled=true;try{const body={name:$('templateName').value.trim()};for(const key of ['type','title','subtitle','accent','content'])body[key]=clone(draft[key]);if($('templateSaveScope')?.value==='slide'){delete body.content.modeDrafts;body.content.slides=[cloneSlideDesign(currentSlide(),draft.content.background)];body.content.background=currentSlide().background||draft.content.background}const result=await api('/api/templates','POST',body);savedTemplates.push(result.template);dialog.close();toast('내 템플릿에 저장했습니다.')}catch(e){$('templateSaveError').textContent=e.message}finally{submit.disabled=false}}}
async function importTemplate(event){const file=event.target.files[0];if(!file)return;try{if(file.size>512000)throw Error('템플릿 JSON은 512KB 이내로 선택해 주세요.');const value=JSON.parse(await file.text());if(!['nuvistage-template','pisignage-template'].includes(value.format)||value.version!==1)throw Error('Nuvistage에서 내보낸 템플릿 JSON을 선택해 주세요.');const body={name:value.name};for(const key of ['type','title','subtitle','accent','content'])body[key]=value[key];const result=await api('/api/templates','POST',body);savedTemplates.push(result.template);toast('내 템플릿으로 불러왔습니다.');if(page==='editor')openTemplates();else templatesPage()}catch(error){toast(error.message)}finally{event.target.value=''}}
function mainScreenSettings(){const form=$('infoForm');if(!form||page!=='system')return;const section=document.createElement('section');section.className='player-config';section.innerHTML=`<h3>메인 라즈베리파이의 주 화면</h3><label class="field">주 메뉴판 / 메인 화면<select id="mainScreen"> <option value="">아직 배정하지 않음</option>${screens.map(s=>`<option value="${s.id}" ${settings.mainScreenId===s.id?'selected':''}>${esc(s.name)} · ${types[s.type]}</option>`).join('')}</select></label><p class="muted">메인 서버의 화면도 등록된 Player 장치에 배정해 출력할 수 있습니다. 장치 관리에서 각 Raspberry Pi에 사용할 화면을 선택하세요.</p><div class="actions" style="margin-top:14px"><button class="btn" type="button" id="saveMainScreen">배정 저장</button><button class="btn" type="button" id="connectMainScreen">장치 관리 열기</button></div>`;form.nextElementSibling.append(section);$('mainScreen').onchange=()=>{};$('saveMainScreen').onclick=handle(async()=>{settings=await api('/api/settings','PATCH',{revision:settings.revision,mainScreenId:$('mainScreen').value});toast('메인 서버의 주 화면을 배정했습니다.')});$('connectMainScreen').onclick=()=>navigate('/devices')}
async function init(){
 try{account=await api('/api/auth/status');if(!account.authenticated){location.replace('/login?next='+encodeURIComponent('/#/'+page+(params.size?'?'+params.toString():'')));return}csrfToken=account.csrfToken;const sections=[['한눈에 보기',[['dashboard','대시보드','전체 화면과 운영 상태']]],['화면 만들기',[['screens','출력 화면','콘텐츠 · 화면 구성'],['devices','장치 관리','등록된 Player · 화면 배정'],['ads','광고판','프로모션과 반복 재생'],['menus','메뉴판','메뉴와 가격 관리'],['templates','템플릿','기본 예시와 내 디자인'],['media','미디어','이미지 · 영상 파일']]],['운영 관리',[['playlists','재생목록','콘텐츠 순서 · 재생 구성'],['groups','장치 그룹','그룹 배정 · 배포'],['schedules','시간표','요일 · 시간 · 기간'],['reports','운영 기록','연결 상태 · 배포 수신']]],['워크스페이스',[['registration','장치 연결 설정','코드 연결 · 등록 잠금'],['system','시스템 정보','사업장과 메인 화면'],['support','문의 안내','연락처와 이용 안내']]]];$('nav').innerHTML=sections.map(([label,links])=>`<div class="nav-section">${label}</div>`+links.map(([p,title,description])=>`<a class="nav-link ${p===page||(page==='editor'&&p==='screens')?'active':''}" href="/${p}" title="${title}" ${p===page?'aria-current="page"':''}>${icon(pages[p][1])}<span class="nav-copy"><span>${title}</span><small>${description}</small></span></a>`).join('')).join('');$('breadcrumb').textContent=pages[page][0];$('accountName').textContent=account.username.slice(0,2).toUpperCase();$('accountName').title=account.username;$('navToggle').innerHTML=icon('hamburger');$('navToggle').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('navToggle').setAttribute('aria-expanded',String(open))};document.addEventListener('click',event=>{if(!event.target.closest('#sidebar,#navToggle')){document.body.classList.remove('nav-open');$('navToggle').setAttribute('aria-expanded','false')}});$('main').innerHTML='<div class="loading">워크스페이스를 불러오는 중…</div>';
 const [s,m,config,sys,templates,players,fonts]=await Promise.all([api('/api/screens'),api('/api/media'),api('/api/settings'),api('/api/system'),api('/api/templates'),api('/api/players'),api('/api/fonts')]);customFonts=fonts.fonts;installCustomFonts(customFonts);screens=s.screens;media=m.media;settings=config;system=sys;savedTemplates=templates.templates;connections=players.players;
 document.querySelector('.side-foot').innerHTML=`<span class="local-dot"></span>${esc(account.username)} · 관리자<button class="btn" id="logout">${icon('external')}로그아웃</button>`;$('logout').onclick=handle(async()=>{if((dirty||[...workspaces.values()].some(w=>w.dirty)||[...formWorkspaces.values()].some(w=>w.dirty))&&!confirm('저장하지 않은 변경사항을 버리고 로그아웃할까요?'))return;await api('/api/auth/logout','POST',{});dirty=false;workspaces.clear();formWorkspaces.clear();location.href='/login'});const collapse=document.createElement('button');collapse.className='sidebar-collapse';collapse.setAttribute('aria-label','사이드바 접기 / 펼치기');collapse.textContent='‹';$('sidebar').append(collapse);try{document.body.classList.toggle('sidebar-collapsed',localStorage.getItem('sidebar-collapsed')==='true')}catch{}collapse.onclick=()=>{const small=document.body.classList.toggle('sidebar-collapsed');collapse.textContent=small?'›':'‹';try{localStorage.setItem('sidebar-collapsed',String(small))}catch{}};
 history.replaceState(null,'','/#/'+page+(params.size?'?'+params.toString():''));await preloadFonts((page==='templates'?[...savedTemplates,...BUILTIN_TEMPLATES]:screens).flatMap(fontsFor));render();updateShell();try{$('nav').scrollTop=Number(sessionStorage.getItem('pisignage-nav-scroll')||0)}catch{}document.title=pages[page][0]+' · Nuvistage';let polling=false;
 setInterval(async()=>{if(polling||document.hidden||$('mediaDialog').open||$('uiDialog').open||$('templateDialog').open)return;polling=true;try{if(page==='dashboard'){const data=await api('/api/screens');if(JSON.stringify(data.screens)!==JSON.stringify(screens)){screens=data.screens;dashboard()}}if(['dashboard','screens','ads','menus'].includes(page)){connections=(await api('/api/players')).players;bindConnections()}}catch(error){toast('서버 연결 상태를 확인해 주세요.')}finally{polling=false}},4000);
 }catch(error){$('main').innerHTML='<section class="empty"><h2>워크스페이스를 불러오지 못했습니다.</h2><p>서버와 로그인 상태를 확인하고 새로고침해 주세요.</p></section>';toast(error.message)}}
init();
